"css": "\n.twofold-opt { color: var(--543912ec-00bd-40f1-a5ea-edcaab7caea5); transition: color 180ms cubic-bezier(0.16, 1, 0.3, 1), background-color 180ms cubic-bezier(0.16, 1, 0.3, 1), transform 120ms cubic-bezier(0.16, 1, 0.3, 1); }\n.twofold-opt:hover { color: var(--4eb6c52a-bd37-4578-a239-77714376d382); }\n.twofold-opt:not(:has(.twofold-aud-input:checked)):hover { background-color: color-mix(in oklab, var(--8e8474f8-bc90-4465-ac11-1631416a8d56) 5%, transparent); }\n.twofold-opt:active { transform: scale(0.985); }\n.twofold-opt:has(.twofold-aud-input:focus-visible) { outline: 2px solid var(--1dba6cb4-93b4-47b3-987f-0dce7cb057ee); outline-offset: -2px; }\n.twofold-aud-input:focus-visible { outline: 2px solid var(--1dba6cb4-93b4-47b3-987f-0dce7cb057ee); }\n.twofold-opt:has(.twofold-aud-input:checked) { color: var(--4eb6c52a-bd37-4578-a239-77714376d382); }\n.twofold-opt-line { color: var(--543912ec-00bd-40f1-a5ea-edcaab7caea5); }\n.twofold-dot { box-shadow: inset 0 0 0 1.5px currentColor; }\n.twofold-dot::after { content: \"\"; width: 8px; height: 8px; border-radius: 50%; background-color: var(--1dba6cb4-93b4-47b3-987f-0dce7cb057ee); opacity: 0; transition: opacity 180ms cubic-bezier(0.16, 1, 0.3, 1); }\n.twofold-opt:has(.twofold-aud-input:checked) .twofold-dot { box-shadow: inset 0 0 0 1.5px var(--1dba6cb4-93b4-47b3-987f-0dce7cb057ee); }\n.twofold-opt:has(.twofold-aud-input:checked) .twofold-dot::after { opacity: 1; }\n.twofold-scene { outline: 1px solid color-mix(in oklab, var(--8e8474f8-bc90-4465-ac11-1631416a8d56) 10%, transparent); outline-offset: -1px; opacity: 0.45; filter: saturate(0.6); transition: opacity 180ms cubic-bezier(0.16, 1, 0.3, 1), filter 180ms cubic-bezier(0.16, 1, 0.3, 1); }\n.twofold-opt:hover .twofold-scene { opacity: 0.85; }\n.twofold-opt:has(.twofold-aud-input:checked) .twofold-scene { opacity: 1; filter: none; }\n.twofold-glide { transition: transform 280ms cubic-bezier(0.16, 1, 0.3, 1); }\n.twofold-switch-rows:has(.twofold-aud-input[value=\"business\"]:checked) .twofold-glide { transform: translateY(calc(100% + 4px)); }\n@media (max-width: 576px) {\n\t.twofold-switch-rows:has(.twofold-aud-input[value=\"business\"]:checked) .twofold-glide { transform: translateX(calc(100% + 4px)); }\n}\n@media (prefers-reduced-motion: reduce) { .twofold-opt, .twofold-dot::after, .twofold-scene, .twofold-glide { transition: none; } }\n",
"js": "\nconst live = typeof window !== \"undefined\";\nconst uid = String(this.dataset.blockUid || \"plate\").replace(/[^a-zA-Z0-9_-]/g, \"\");\nconst inputs = Array.from(this.querySelectorAll(\".twofold-aud-input\"));\ninputs.forEach((input) => input.setAttribute(\"name\", \"twofold-aud-\" + uid));\nif (!live) return;\nif (typeof this.twofoldOff === \"function\") this.twofoldOff();\n\nconst twofoldKey = \"twofold-audience\";\nconst twofoldRoot = document.documentElement;\nconst twofoldRead = () => {\n\tconst now = twofoldRoot.dataset.audience;\n\tif (now === \"personal\" || now === \"business\") return now;\n\tlet saved = \"personal\";\n\ttry {\n\t\tif (window.localStorage.getItem(twofoldKey) === \"business\") saved = \"business\";\n\t} catch (error) {}\n\treturn saved;\n};\ntwofoldRoot.classList.add(\"twofold-js\");\ntwofoldRoot.dataset.audience = twofoldRead();\n// transitions wait until the page has arrived (twofold_styles holds them off until then)\nif (!window.twofoldSettling) {\n\twindow.twofoldSettling = true;\n\tconst twofoldSettle = () => requestAnimationFrame(() => requestAnimationFrame(() => twofoldRoot.classList.add(\"twofold-settled\")));\n\tif (document.readyState === \"loading\") document.addEventListener(\"DOMContentLoaded\", twofoldSettle, { once: true });\n\telse twofoldSettle();\n}\nconst twofoldSet = (aud) => {\n\tif (aud !== \"personal\" && aud !== \"business\") return;\n\tif (twofoldRoot.dataset.audience === aud) return;\n\ttwofoldRoot.dataset.audience = aud;\n\ttry {\n\t\twindow.localStorage.setItem(twofoldKey, aud);\n\t} catch (error) {}\n\tevents.dispatch(twofoldKey, { audience: aud });\n};\n\nconst paint = (aud) => inputs.forEach((input) => {\n\tinput.checked = input.value === aud;\n});\npaint(twofoldRead());\nconst onChange = (event) => {\n\tconst input = event.target;\n\tif (input && input.classList && input.classList.contains(\"twofold-aud-input\") && input.checked) twofoldSet(input.value);\n};\nthis.addEventListener(\"change\", onChange);\nconst unlisten = events.listen(twofoldKey, (data) => paint(data && data.audience));\nconst off = () => {\n\tthis.removeEventListener(\"change\", onChange);\n\tif (typeof unlisten === \"function\") unlisten();\n\tthis.twofoldOff = null;\n};\nthis.twofoldOff = off;\nreturn off;\n"
